input.command:
cat > /tmp/opencode/shot.mjs <<'EOF'
import { chromium } from 'playwright';
const browser = await chromium.launch({ args: ['--no-sandbox'] });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
await page.goto('https://derelict-game.vercel.app/', { waitUntil: 'networkidle', timeout: 45000 });
await page.waitForTimeout(6000);
await page.screenshot({ path: '/tmp/opencode/shot-title.png' });
console.log('title done');
// dump visible text
const text = await page.innerText('body');
console.log(text.slice(0, 3000));
// list buttons
const btns = await page.$$eval('button', els => els.map(e => e.innerText.slice(0,80)));
console.log('BUTTONS:', JSON.stringify(btns.slice(0,30)));
// try clicking primary button
try {
  const primary = page.locator('.opening-primary, button').first();
  await primary.click({ timeout: 5000 });
  await page.waitForTimeout(4000);
  await page.screenshot({ path: '/tmp/opencode/shot-after.png' });
  console.log('after-click done');
  console.log((await page.innerText('body')).slice(0, 3000));
} catch(e) { console.log('click fail', e.message); }
await browser.close();
EOF
