cat > /tmp/opencode/shot3.mjs <<'EOF'
import { chromium } from 'playwright-core';
const browser = await chromium.launch({ executablePath: '/usr/bin/google-chrome', args: ['--no-sandbox'] });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
await page.goto('https://derelict-game.vercel.app/', { waitUntil: 'networkidle', timeout: 45000 });
await page.waitForTimeout(3000);
await page.getByRole('button', { name: /WAKE UP/i }).click();
await page.waitForTimeout(8000);
// dismiss cold-open dialog if present
try { await page.keyboard.press('Escape'); await page.waitForTimeout(1000); } catch {}
await page.evaluate(() => window.scrollTo(0, 900));
await page.waitForTimeout(1000);
await page.screenshot({ path: '/tmp/opencode/shot-cryo2.png', fullPage: false });
console.log('scroll1:', (await page.innerText('body')).slice(0, 5000).replace(/\n+/g,' | '));
await page.evaluate(() => window.scrollTo(0, 3000));
await page.waitForTimeout(800);
await page.screenshot({ path: '/tmp/opencode/shot-cryo3.png' });
await browser.close();
EOF
